function validate(input) {
  const [{ Countries = [], Weather = [] }] = input;
  const countries = new Set(), readings = new Set();
  for (const [id] of Countries) {
    if (id === null) return 'Every country needs a country_id.';
    if (countries.has(id)) return `country_id ${id} appears twice in Countries.`;
    countries.add(id);
  }
  for (const [id, state, day] of Weather) {
    if (id === null || day === null || state === null) return 'Every reading needs a country_id, a weather_state and a day.';
    if (!countries.has(id)) return `Weather names country_id ${id}, which is not in Countries.`;
    const key = `${id}/${day}`;
    if (readings.has(key)) return `Country ${id} has two readings on ${day}.`;
    readings.add(key);
  }
  return null;
}

