function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['USA', 'Australia', 'Peru', 'China', 'Morocco', 'Spain', 'Chile', 'Kenya'];
  const small = size === 'small';
  const countryCount = small ? Math.floor(rand() * 6) : 120;
  const Countries = [];
  for (let i = 0; i < countryCount; i++) Countries.push([i * 2 + 1, small ? names[i] : `Land${i + 1}`]);
  // Small sets cluster dates around the November 2019 boundaries and temperatures around 15 and 25.
  const smallDays = ['2019-10-31', '2019-11-01', '2019-11-02', '2019-11-15', '2019-11-29', '2019-11-30', '2019-12-01', '2020-11-10', '2018-11-20'];
  const smallStates = [-3, 0, 10, 14, 15, 16, 20, 24, 25, 26, 30];
  const day = () => {
    if (small) return pick(smallDays);
    const month = pick(['10', '11', '11', '11', '12']);
    const year = rand() < 0.85 ? '2019' : '2020';
    return `${year}-${month}-${String(1 + Math.floor(rand() * 30)).padStart(2, '0')}`;
  };
  const Weather = [], seen = new Set();
  const target = countryCount === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  for (let attempt = 0; Weather.length < target && attempt < target * 4; attempt++) {
    const [id] = pick(Countries), when = day(), key = `${id}/${when}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Weather.push([id, small ? pick(smallStates) : Math.floor(rand() * 46) - 5, when]);
  }
  return [{ Countries, Weather }];
}
